require 'bunny'
require 'json'
require 'securerandom'
require 'digest'
require 'base64'

module AuthValidator
  HMAC_SECRET = ENV['HMAC_SECRET'] || SecureRandom.hex(32)
  TOKEN_TTL = 300 # 5 minutes

  def self.generate_token(service_name, timestamp)
    payload = "#{service_name}:#{timestamp}"
    sig = OpenSSL::HMAC.hexdigest('SHA256', HMAC_SECRET, payload)
    Base64.strict_encode64("#{payload}:#{sig}")
  end

  def self.validate_token(token)
    decoded = Base64.strict_decode64(token)
    parts = decoded.split(':')
    return false unless parts.length == 3

    service_name, timestamp, signature = parts
    expected_sig = OpenSSL::HMAC.hexdigest('SHA256', HMAC_SECRET, "#{service_name}:#{timestamp}")

    return false unless secure_compare(expected_sig, signature)
    return false unless (Time.now.to_i - timestamp.to_i).abs < TOKEN_TTL

    service_name
  end

  def self.secure_compare(a, b)
    return false unless a.bytesize == b.bytesize
    l = a.unpack('C*')
    r = b.unpack('C*')
    result = 0
    l.zip(r) { |x, y| result |= x ^ y }
    result == 0
  end
end

module MessageSanitizer
  # Validates message format conforms to protocol spec
  # Format: HEADER{key=value;key=value}BODY{content}
  HEADER_PATTERN = /\AHEADER\{([a-zA-Z0-9_]+=[^;{}]*(?:;[a-zA-Z0-9_]+=[^;{}]*)*)\}BODY\{(.*)\}\z/m

  # Validates routing keys follow naming convention
  # service.action.sub_action with optional version suffix
  ROUTING_KEY_PATTERN = /\A[a-z]+(?:\.[a-z]+)*(?:_v\d+)?\z/

  # Content-type validation for structured payloads
  # Allows nested type annotations like: type<subtype<innertype>>
  CONTENT_TYPE_PATTERN = /\A[a-z]+(?:<[a-z]+(?:<[a-z]+>)*>)*\z/

  def self.validate_message_format(raw_message)
    return nil unless raw_message.is_a?(String)
    return nil if raw_message.length > 65536

    match = HEADER_PATTERN.match(raw_message)
    return nil unless match

    headers_str = match[1]
    body = match[2]

    headers = parse_headers(headers_str)
    return nil unless headers

    { headers: headers, body: body }
  end

  def self.validate_routing_key(key)
    return false unless key.is_a?(String)
    return false if key.length > 128
    ROUTING_KEY_PATTERN.match?(key)
  end

  def self.validate_content_type(ct)
    return false unless ct.is_a?(String)
    return false if ct.length > 256
    CONTENT_TYPE_PATTERN.match?(ct)
  end

  private

  def self.parse_headers(headers_str)
    result = {}
    headers_str.split(';').each do |pair|
      k, v = pair.split('=', 2)
      return nil unless k && v
      result[k] = v
    end
    result
  end
end

class QueueConsumer
  attr_reader :connection, :channel, :queue

  def initialize(queue_name, opts = {})
    @queue_name = queue_name
    @prefetch = opts.fetch(:prefetch, 10)
    @handlers = {}
    @running = false
  end

  def register_handler(routing_pattern, &block)
    @handlers[routing_pattern] = block
  end

  def start
    @connection = Bunny.new(
      host: ENV.fetch('RABBITMQ_HOST', 'localhost'),
      port: ENV.fetch('RABBITMQ_PORT', 5672).to_i,
      vhost: ENV.fetch('RABBITMQ_VHOST', '/'),
      user: ENV.fetch('RABBITMQ_USER', 'guest'),
      password: ENV.fetch('RABBITMQ_PASS', 'guest')
    )
    @connection.start
    @channel = @connection.create_channel
    @channel.prefetch(@prefetch)
    @queue = @channel.queue(@queue_name, durable: true)
    @running = true

    @queue.subscribe(manual_ack: true, block: false) do |delivery_info, properties, payload|
      process_message(delivery_info, properties, payload)
    end
  end

  def stop
    @running = false
    @channel&.close
    @connection&.close
  end

  private

  def process_message(delivery_info, properties, payload)
    # Step 1: Authenticate the sending service
    auth_token = properties.headers&.dig('X-Service-Token')
    unless auth_token
      @channel.nack(delivery_info.delivery_tag, false, false)
      return
    end

    service_name = AuthValidator.validate_token(auth_token)
    unless service_name
      @channel.nack(delivery_info.delivery_tag, false, false)
      return
    end

    # Step 2: Validate routing key format
    routing_key = delivery_info.routing_key
    unless MessageSanitizer.validate_routing_key(routing_key)
      @channel.nack(delivery_info.delivery_tag, false, false)
      return
    end

    # Step 3: Validate content type if specified
    content_type = properties.content_type
    if content_type && !MessageSanitizer.validate_content_type(content_type)
      @channel.nack(delivery_info.delivery_tag, false, false)
      return
    end

    # Step 4: Parse and validate message structure
    parsed = MessageSanitizer.validate_message_format(payload)
    unless parsed
      @channel.nack(delivery_info.delivery_tag, false, false)
      return
    end

    # Step 5: Route to appropriate handler
    handler = find_handler(routing_key)
    if handler
      handler.call(service_name, parsed[:headers], parsed[:body])
      @channel.ack(delivery_info.delivery_tag)
    else
      @channel.nack(delivery_info.delivery_tag, false, true) # requeue
    end
  rescue StandardError => e
    @channel.nack(delivery_info.delivery_tag, false, false)
  end

  def find_handler(routing_key)
    @handlers.each do |pattern, handler|
      return handler if routing_key.start_with?(pattern)
    end
    nil
  end
end
